import json, numpy as np, importlib.util, sys, os, time
from pathlib import Path
ROOT=Path('/workspace/IOAI/ioai2-competition-runs-task3-formal-deadline-20260806T123442CST/ioai-2026-task-3-westlake-nlp-48/project'); DATA=ROOT/'input/competition'
