E=np.load(DATA/'public_embeddings.npy').astype(np.float32); E/=np.linalg.norm(E,axis=1,keepdims=True)
S=E@E.T; n=len(words)

class Hard:
 def __init__(self,E): self.S=E@E.T; self.n=len(E)
 def new_game(self): self.c=np.ones(self.n,bool); self.used=np.zeros(self.n,bool)
 def respond(self,m):
  i1=wi[m['word1'].casefold()]; i2=wi[m['word2'].casefold()]; v=m['verdict'];
  if v in ('first','second'):
   b,w=(i1,i2) if v=='first' else (i2,i1); self.c &= self.S[b]>=self.S[w]
  self.c[self.used]=False
  if not self.c.any(): self.c[:]=True; self.c[self.used]=False
  ch=wi[m['winner_word'].casefold()]; al=np.flatnonzero(self.c); p=int(al[np.argmax(self.S[ch,al])]); self.used[p]=True; return words[p]

class Soft:
 def __init__(self,E,temp=.1,q=.8,alpha=0,mode='mix',clip=0):
  self.S=E@E.T; self.n=len(E); self.temp=temp; self.q=q; self.alpha=alpha; self.mode=mode; self.clip=clip
 def new_game(self): self.lp=np.zeros(self.n,np.float32); self.used=np.zeros(self.n,bool); self.t=0
 def respond(self,m):
  i1=wi[m['word1'].casefold()]; i2=wi[m['word2'].casefold()]; v=m['verdict'];
  if v in ('first','second'):
   b,w=(i1,i2) if v=='first' else (i2,i1); z=np.clip((self.S[:,b]-self.S[:,w])/self.temp,-20,20); pr=1/(1+np.exp(-z)); pr=self.q*pr+(1-self.q)*.5; self.lp += np.log(pr).astype(np.float32)
  self.lp[self.used]=-1e9
  ch=wi[m['winner_word'].casefold()]; al=~self.used
  if self.mode=='top': score=self.lp.copy()
  elif self.mode=='mix': score=self.lp + self.alpha*self.S[ch]
  elif self.mode=='neighbor':
   # posterior-weighted nearest score; normalize lp for stability
   x=self.lp-np.max(self.lp); score=x + self.alpha*self.S[ch]
  elif self.mode=='rank':
   score=self.lp + self.alpha*np.argsort(np.argsort(self.S[ch]))/self.n
  p=int(np.argmax(np.where(al,score,-1e9))); self.used[p]=True; return words[p]

class RankWalk:
 def __init__(self,E,k=50,alpha=0,temperature=0): self.S=E@E.T; self.n=len(E); self.k=k; self.alpha=alpha
 def new_game(self): self.used=np.zeros(self.n,bool); self.lp=np.zeros(self.n,np.float32)
 def respond(self,m):
  i1=wi[m['word1'].casefold()]; i2=wi[m['word2'].casefold()]; v=m['verdict'];
  if v in ('first','second'):
   b,w=(i1,i2) if v=='first' else (i2,i1); margin=self.S[:,b]-self.S[:,w];
   # rank sign, discounted update
   self.lp += np.where(margin>=0,1.,-1.)
  self.lp[self.used]=-1e9
  ch=wi[m['winner_word'].casefold()]; al=~self.used
  # robust rank aggregate: posterior score plus champion rank percentile
  ranks=np.argsort(np.argsort(-self.S[ch]))
  score=self.lp - self.alpha*ranks/self.n
  p=int(np.argmax(np.where(al,score,-1e9))); self.used[p]=True; return words[p]

# direct sim
def play(P,Ejudge,secrets,noise_q=0,seed=0,return_hist=False):
 rng=np.random.default_rng(seed); vals=[]; turns=[]
 for sec in secrets:
  P.new_game(); si=wi[sec]; w1='lamp';w2='potato'; solved=None
  for t in range(1,31):
   i1=wi[w1];i2=wi[w2]; d=float(Ejudge[si]@Ejudge[i1]-Ejudge[si]@Ejudge[i2])
   if noise_q:
    # q fixed flip, deterministic random
    first=(rng.random()>=noise_q) if d>0 else (rng.random()<noise_q)
   else: first=d>1e-12
   if abs(d)<=1e-12 and not noise_q: ver='same';win=w1
   elif first:ver='first';win=w1
   else:ver='second';win=w2
   prop=P.respond({'turn':t,'winner_word':win,'verdict':ver,'word1':w1,'word2':w2})
   if prop==sec: solved=t;break
   w1,w2=win,prop
  turns.append(solved); vals.append(0 if solved is None else 1-.02*max(0,solved-10))
